INSERT INTO feature VALUES('issue-dependencies','workflow','Issue dependencies and labels set by the tools',NULL,'implemented','ordinary',NULL,'Every unit issue states what it waits on in `## After`, and the tools set it as the GitHub `blocked by` dependency: `unit:check` refuses a missing or malformed section and an unset dependency, `--fix` sets it, `issue:file` sets it as it files and links the issue under its epic, an epic is blocked by each open sub-issue, `epic:order --chain` sets a ladder''s chain, `claim:next` passes over a blocked issue and ranks by priority within each bucket, and the nightly `report:deps` lists each dependency stated in prose and not set. `issue:file` refuses an issue short of one `kind:`, `area:`, `priority:` and `effort:` label, a missing priority or effort taking its kind''s default from one table.',NULL,'.config/issues/deps.json .config/claims/next.json .config/reports/report.json .config/issues/cases.json',NULL,NULL);
